using System;

struct PointS { public int X; }
class PointC { public int X; }
class Holder { public PointS Field; }   // struct field lives INSIDE the heap object

class Program
{
    static void Main()
    {
        PointS a = new PointS { X = 1 };
        PointS b = a;            // value type: copy
        b.X = 99;
        Console.WriteLine("struct: a.X=" + a.X + " b.X=" + b.X);

        PointC c = new PointC { X = 1 };
        PointC d = c;            // reference type: same object
        d.X = 99;
        Console.WriteLine("class : c.X=" + c.X + " d.X=" + d.X);

        // A struct field sits inside its containing heap object.
        Holder h = new Holder();
        h.Field.X = 5;           // legal: h.Field is a variable, not a copy
        Console.WriteLine("holder.Field.X=" + h.Field.X);

        // Struct array elements live inside the array object (heap).
        PointS[] arr = new PointS[3];
        arr[1].X = 7;
        Console.WriteLine("arr = " + arr[0].X + "," + arr[1].X + "," + arr[2].X);

        // A captured local is hoisted into a heap closure object.
        int counter = 0;
        Action inc = () => counter++;
        inc(); inc();
        Console.WriteLine("captured counter=" + counter);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;

interface IBump { void Bump(); }
struct Counter : IBump
{
    public int N;
    public void Bump() { N++; }
}

class Program
{
    static void Main()
    {
        int x = 3;
        object boxed = x;               // BOXING: heap allocation + copy
        x = 5;
        Console.WriteLine("x=" + x + " boxed=" + boxed);   // box is a separate copy

        object b1 = x, b2 = x;          // each boxing creates a new object
        Console.WriteLine("same box? " + ReferenceEquals(b1, b2));

        try { long l = (long)boxed; Console.WriteLine(l); }  // unbox needs exact type
        catch (InvalidCastException) { Console.WriteLine("unbox as long fails"); }
        Console.WriteLine("unbox as int ok: " + (int)boxed);

        // Hidden boxing: struct -> interface
        Counter c = new Counter();
        IBump i = c;                    // boxes a copy
        i.Bump(); i.Bump();
        Console.WriteLine("original N=" + c.N + ", boxed copy bumped twice");

        // Non-generic ArrayList boxes every int; List<int> does not.
        ArrayList old = new ArrayList();
        List<int> gen = new List<int>();
        for (int k = 0; k < 3; k++) { old.Add(k); gen.Add(k); }
        Console.WriteLine("ArrayList items are objects: " + old[0].GetType() + ", " + (old[0] is object));
        Console.WriteLine("List<int> sum without boxing: " + (gen[0] + gen[1] + gen[2]));
    }
}

using System;
using System.Runtime.CompilerServices;

class Program
{
    class Temp { public byte[] Data = new byte[100]; }

    [MethodImpl(MethodImplOptions.NoInlining)]
    static WeakReference MakeGarbage()
    {
        Temp t = new Temp();               // allocated in gen 0 (bump pointer)
        return new WeakReference(t);       // weak: does not keep t alive
    }

    static void Main()
    {
        WeakReference dead = MakeGarbage();
        Console.WriteLine("before GC alive? " + dead.IsAlive);   // not collected yet

        Temp keep = new Temp();            // a strong reference keeps it alive
        WeakReference live = new WeakReference(keep);

        GC.Collect();                      // demo only: most objects die young
        GC.WaitForPendingFinalizers();

        Console.WriteLine("short-lived object alive after GC? " + dead.IsAlive);
        Console.WriteLine("rooted object alive after GC?       " + live.IsAlive);
        Console.WriteLine("keep still usable: " + keep.Data.Length);
        // Survivors of a collection are promoted to an older generation,
        // so the next gen0 collection does not scan them again.
    }
}

using System;
using System.Collections.Generic;

class Program
{
    const int LohLimit = 85000;               // bytes

    static void Main()
    {
        Console.WriteLine("int[] goes to the LOH from " + (LohLimit / 4) + " elements (4 bytes each)");

        // List<int> doubles its internal array; watch when it crosses the limit.
        List<int> list = new List<int>();
        int lastCap = -1;
        for (int i = 0; i < 40000; i++)
        {
            list.Add(i);
            if (list.Capacity != lastCap)
            {
                lastCap = list.Capacity;
                long bytes = (long)lastCap * 4;
                string where = bytes >= LohLimit ? "LOH (gen 2 only)" : "normal heap";
                if (lastCap >= 8192) Console.WriteLine("capacity " + lastCap + " = " + bytes + " bytes -> " + where);
            }
        }
        // Each doubling past the limit allocates a new big array and abandons the old one.
        // Fix: new List<int>(expectedCount), or pool the buffers.
    }
}

using System;

class Resource : IDisposable
{
    string name;
    bool disposed;
    public Resource(string n) { name = n; }

    public void Dispose()                  // deterministic cleanup by the owner
    {
        if (disposed) return;
        disposed = true;
        Console.WriteLine(name + ": Dispose() called, cleaned up now");
        GC.SuppressFinalize(this);         // finalizer no longer needed
    }

    ~Resource()                            // safety net run by the GC
    {
        Console.WriteLine(name + ": finalizer ran (owner forgot Dispose)");
    }
}

class Program
{
    static void Forget() { new Resource("forgotten"); }   // never disposed

    static void Main()
    {
        using (Resource r = new Resource("with-using"))
        {
            Console.WriteLine("using block body");
        }                                   // Dispose runs here, always

        Forget();
        GC.Collect();                       // demo only: forces the finalizer to be queued
        GC.WaitForPendingFinalizers();      // wait for the finalizer thread
        Console.WriteLine("done");
    }
}

using System;
using System.IO;

class Holder : IDisposable
{
    MemoryStream managed = new MemoryStream();   // managed field
    bool disposed;
    string name;
    public Holder(string n) { name = n; }

    public void Dispose()
    {
        Dispose(true);                           // called by the owner
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (disposed) return;
        disposed = true;
        if (disposing)
        {
            // safe: other managed objects are still alive
            managed.Dispose();
            Console.WriteLine(name + ": disposing=true, managed field disposed");
        }
        else
        {
            // finalizer thread: touch only unmanaged state
            Console.WriteLine(name + ": disposing=false, only unmanaged cleanup");
        }
    }

    ~Holder() { Dispose(false); }
}

class Program
{
    static void Leak() { new Holder("leaked"); }

    static void Main()
    {
        using (Holder h = new Holder("explicit")) { }
        Leak();
        GC.Collect();
        GC.WaitForPendingFinalizers();
    }
}

using System;

class Program
{
    // Parse a non-negative int from a slice of chars, no substring allocated.
    static int ParseInt(ReadOnlySpan<char> s)
    {
        int v = 0;
        for (int i = 0; i < s.Length; i++) v = v * 10 + (s[i] - '0');
        return v;
    }

    static void Main()
    {
        int[] data = { 1, 2, 3, 4, 5, 6 };
        Span<int> window = new Span<int>(data).Slice(2, 3);   // O(1), no copy
        window[0] = 99;                                       // writes through to the array
        Console.WriteLine("data[2] after slice write: " + data[2]);
        Console.WriteLine("slice length: " + window.Length);

        string text = "12,345,6789";
        ReadOnlySpan<char> rest = text.AsSpan();
        int sum = 0;
        while (rest.Length > 0)
        {
            int comma = rest.IndexOf(',');
            ReadOnlySpan<char> part = comma < 0 ? rest : rest.Slice(0, comma);
            sum += ParseInt(part);                            // zero allocations
            rest = comma < 0 ? ReadOnlySpan<char>.Empty : rest.Slice(comma + 1);
        }
        Console.WriteLine("input: " + text + " -> sum = " + sum);
        // Time O(n), extra space O(1).
    }
}

using System;
using System.Threading.Tasks;

class Buffer
{
    // Span<T> cannot be a field of a class; Memory<T> can.
    public Memory<int> Data;
}

class Program
{
    static void Fill(Memory<int> mem)       // synchronous part: Span is allowed here
    {
        Span<int> s = mem.Span;
        for (int i = 0; i < s.Length; i++) s[i] = i * 10;
    }

    static async Task FillAsync(Memory<int> mem)
    {
        await Task.Yield();                 // a Span local could not live across this await
        Fill(mem);                          // Memory survives; take .Span after the await
    }

    static void Main()
    {
        int[] backing = new int[5];
        Buffer b = new Buffer();
        b.Data = new Memory<int>(backing).Slice(1, 3);   // stored in a field

        FillAsync(b.Data).Wait();

        Console.WriteLine("backing: " + string.Join(",", backing));
        Console.WriteLine("slice length: " + b.Data.Length);
        Console.WriteLine("slice[1] = " + b.Data.Span[1]);
    }
}

using System;
using System.Buffers;

class Program
{
    static void Main()
    {
        int requested = 10;
        int[] a = ArrayPool<int>.Shared.Rent(requested);
        // Rent returns AT LEAST the requested size (a power-of-two bucket).
        Console.WriteLine("requested " + requested + ", got length " + a.Length);
        try
        {
            for (int i = 0; i < requested; i++) a[i] = i;   // use 'requested', not a.Length
            Console.WriteLine("first 3: " + a[0] + "," + a[1] + "," + a[2]);
        }
        finally
        {
            ArrayPool<int>.Shared.Return(a, clearArray: true);  // always return
        }

        // Pitfall: after Return, the array is usually handed to the next renter.
        int[] x = ArrayPool<int>.Shared.Rent(10);
        ArrayPool<int>.Shared.Return(x);
        int[] y = ArrayPool<int>.Shared.Rent(10);
        Console.WriteLine("renter y got the same array as old x? " + ReferenceEquals(x, y));
        x[0] = 42;                                      // BUG: use after return
        Console.WriteLine("y[0] is now " + y[0] + " (corrupted by the stale reference)");
        ArrayPool<int>.Shared.Return(y);
    }
}

using System;
using System.Runtime.InteropServices;

struct PairS { public int A, B; }
class PairC { public int A, B; }

class Program
{
    static void Main()
    {
        const int N = 1000000;
        Console.WriteLine("struct size: " + Marshal.SizeOf(typeof(PairS)) + " bytes");

        long before = GC.GetTotalMemory(true);
        PairS[] structs = new PairS[N];            // one block, values inline
        long structBytes = GC.GetTotalMemory(true) - before;

        before = GC.GetTotalMemory(true);
        PairC[] objects = new PairC[N];            // N references...
        for (int i = 0; i < N; i++) objects[i] = new PairC();   // ...plus N objects
        long objectBytes = GC.GetTotalMemory(true) - before;

        Console.WriteLine("struct array about 8 MB: " + (structBytes > 7000000 && structBytes < 9000000));
        Console.WriteLine("object version uses at least 3x more: " + (objectBytes > 3 * structBytes));
        GC.KeepAlive(structs); GC.KeepAlive(objects);
        // Struct array: contiguous, cache friendly, no per-item GC tracking.
    }
}

using System;
using System.Collections.Generic;

struct P { public int X; }

class Program
{
    static void Main()
    {
        List<P> list = new List<P> { new P { X = 0 } };

        // list[0].X = 1;          // compile error CS1612: the indexer returns a copy
        P copy = list[0];
        copy.X = 1;
        Console.WriteLine("after editing the copy: list[0].X = " + list[0].X);

        list[0] = copy;            // fix: write the modified value back
        Console.WriteLine("after write-back:      list[0].X = " + list[0].X);

        P[] arr = new P[1];
        arr[0].X = 5;              // arrays give direct access to the element
        Console.WriteLine("array element edited in place: " + arr[0].X);

        // Immutable style: replace the whole value instead of mutating.
        list[0] = new P { X = list[0].X + 1 };
        Console.WriteLine("replaced value: list[0].X = " + list[0].X);
    }
}

using System;
using System.Runtime.CompilerServices;

class Cache
{
    public byte[] Big = new byte[1000000];   // long-lived object holding a large field
}

class Program
{
    [MethodImpl(MethodImplOptions.NoInlining)]
    static WeakReference Track(Cache c) { return new WeakReference(c.Big); }

    static void Main()
    {
        Cache c = new Cache();
        WeakReference w = Track(c);

        GC.Collect();
        Console.WriteLine("big buffer alive while field set: " + w.IsAlive);

        c.Big = null;                         // here nulling a FIELD does matter
        GC.Collect();
        Console.WriteLine("big buffer alive after field = null: " + w.IsAlive);

        // Nulling a LOCAL at the end of a method is pointless: the JIT already
        // knows a local is dead after its last use.
        GC.KeepAlive(c);                      // keeps the Cache object itself alive to here
    }
}
